/**
 * doc-anchor-guard: GitHub Compatible Heading Slugger
 * Converts markdown heading text into the exact slug anchor generated by GitHub/GitLab.
 */

export class GitHubSlugger {
  constructor() {
    this.occurrences = new Map();
  }

  /**
   * Resets slug count state for a new file
   */
  reset() {
    this.occurrences.clear();
  }

  /**
   * Generates slug for a heading string.
   * e.g. "How to Install (v2.0)!" -> "how-to-install-v20"
   * Handles collision suffix: "Options" -> "options", then "options-1"
   * @param {string} rawHeading
   * @returns {string}
   */
  slug(rawHeading) {
    if (!rawHeading) return '';

    // 1. Lowercase
    let clean = rawHeading.trim().toLowerCase();

    // 2. Remove markdown formatting like bold, italics, inline code backticks, links
    clean = clean.replace(/`([^`]+)`/g, '$1');
    clean = clean.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');
    clean = clean.replace(/[*_~]/g, '');

    // 3. Remove punctuation & special characters (preserve letters, digits, whitespace, hyphens)
    // Characters like ! ? . , ( ) [ ] { } : ; @ / \ " ' are stripped
    clean = clean.replace(/[^\p{L}\p{N}\s-]/gu, '');

    // 4. Convert whitespace to hyphens
    clean = clean.replace(/\s+/g, '-');

    // 5. Deduplicate and assign collision suffix if already seen in this file
    const count = this.occurrences.get(clean) || 0;
    this.occurrences.set(clean, count + 1);

    if (count > 0) {
      return `${clean}-${count}`;
    }
    return clean;
  }
}

